// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IDiamondCut } from "../DiamondInterfaces/IDiamondCut.sol";
import { EcosystemLib } from "./EcosystemLib.sol";

library LibDiamond {
    bytes32 constant DIAMOND_STORAGE_POSITION = keccak256("diamond.standard.diamond.storage");
    bytes32 constant APSDEX_STORAGE_POSITION = keccak256("apsdex.storage");
    bytes32 constant ECOSYSTEM_DATA_STORAGE_POSITION = keccak256("ecosystem.data.storage");
    bytes32 constant FLASHLOAN_STORAGE_POSITION = keccak256("flashloan.storage");
    bytes32 constant LENDING_STORAGE_POSITION = keccak256("lending.storage");
    bytes32 constant MOVEPRICE_STORAGE_POSITION = keccak256("moveprice.storage");

    //roles
    bytes32 constant DEFAULT_ADMIN_ROLE = keccak256("DEFAULT_ADMIN_ROLE");

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event DiamondCut(IDiamondCut.FacetCut[] _diamondCut, address _init, bytes _calldata);

    struct FacetAddressAndPosition {
        address facetAddress;
        uint96 functionSelectorPosition;
    }

    struct FacetFunctionSelectors {
        bytes4[] functionSelectors;
        uint256 facetAddressPosition;
    }

    struct DiamondStorage {
        mapping(bytes4 => FacetAddressAndPosition) selectorToFacetAndPosition;
        mapping(address => FacetFunctionSelectors) facetFunctionSelectors;
        address[] facetAddresses;
        mapping(bytes4 => bool) supportedInterfaces;
        address contractOwner;
    }

    struct APSDEXStorage {
        IERC20 token;
        uint256 ethReserve;
        uint256 apsReserve;
        uint256 totalLiquidity;
        bool initialized;
        mapping(address => uint256) liquidity;
    }

    struct EcosystemDataStorage {
        EcosystemLib.Data data;
    }

    struct FlashLoanFacetStorage {
        address payable owner;
        mapping(address => uint256) userOwnedFunds;
    }

    struct LendingPosition {
        uint256 collateralETH;
        uint256 borrowedAPS;
        uint256 borrowTimestamp;
        uint256 riskTimestamp;
        uint256 stakeTimestamp;
    }

    struct LendingFacetStorage {
        address aps;
        address apsDex;
        mapping(address => LendingPosition) positions;
    }

    struct MovePriceFacetStorage {
        address aps;
        address apsDex;
    }

    function diamondStorage() internal pure returns (DiamondStorage storage ds) {
        bytes32 position = DIAMOND_STORAGE_POSITION;
        assembly {
            ds.slot := position
        }
    }

    function apsdexStorage() internal pure returns (APSDEXStorage storage ds) {
        bytes32 position = APSDEX_STORAGE_POSITION;
        assembly {
            ds.slot := position
        }
    }

    function ecosystemDataStorage() internal pure returns (EcosystemDataStorage storage eds) {
        bytes32 position = ECOSYSTEM_DATA_STORAGE_POSITION;
        assembly {
            eds.slot := position
        }
    }

    function flashLoanFacetStorage() internal pure returns (FlashLoanFacetStorage storage fs) {
        bytes32 position = FLASHLOAN_STORAGE_POSITION;
        assembly {
            fs.slot := position
        }
    }

    function lendingFacetStorage() internal pure returns (LendingFacetStorage storage ls) {
        bytes32 position = LENDING_STORAGE_POSITION;
        assembly {
            ls.slot := position
        }
    }

    function movePriceFacetStorage() internal pure returns (MovePriceFacetStorage storage ms) {
        bytes32 position = MOVEPRICE_STORAGE_POSITION;
        assembly {
            ms.slot := position
        }
    }

    function setContractOwner(address _newOwner) internal {
        DiamondStorage storage ds = diamondStorage();
        address previousOwner = ds.contractOwner;
        ds.contractOwner = _newOwner;
        emit OwnershipTransferred(previousOwner, _newOwner);
    }

    function contractOwner() internal view returns (address contractOwner_) {
        contractOwner_ = diamondStorage().contractOwner;
    }

    function enforceIsContractOwner() internal view {
        require(msg.sender == diamondStorage().contractOwner, "LibDiamond: Must be contract owner");
    }

    function diamondCut(
        IDiamondCut.FacetCut[] memory _diamondCut,
        address _init,
        bytes memory _calldata
    ) internal {
        for (uint256 facetIndex; facetIndex < _diamondCut.length; facetIndex++) {
            IDiamondCut.FacetCutAction action = _diamondCut[facetIndex].action;
            if (action == IDiamondCut.FacetCutAction.Add) {
                addFunctions(_diamondCut[facetIndex].facetAddress, _diamondCut[facetIndex].functionSelectors);
            } else if (action == IDiamondCut.FacetCutAction.Replace) {
                replaceFunctions(_diamondCut[facetIndex].facetAddress, _diamondCut[facetIndex].functionSelectors);
            } else if (action == IDiamondCut.FacetCutAction.Remove) {
                removeFunctions(_diamondCut[facetIndex].facetAddress, _diamondCut[facetIndex].functionSelectors);
            } else {
                revert("LibDiamond: Incorrect FacetCutAction");
            }
        }

        emit DiamondCut(_diamondCut, _init, _calldata);
        initializeDiamondCut(_init, _calldata);
    }

    function addFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        require(_facetAddress != address(0), "LibDiamond: Add facet can't be address(0)");
        enforceHasContractCode(_facetAddress, "LibDiamond: Add facet has no code");

        DiamondStorage storage ds = diamondStorage();
        uint256 selectorCount = _functionSelectors.length;
        require(selectorCount > 0, "LibDiamond: No selectors in facet to cut");

        if (ds.facetFunctionSelectors[_facetAddress].functionSelectors.length == 0) {
            ds.facetFunctionSelectors[_facetAddress].facetAddressPosition = ds.facetAddresses.length;
            ds.facetAddresses.push(_facetAddress);
        }

        for (uint256 selectorIndex; selectorIndex < selectorCount; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds.selectorToFacetAndPosition[selector].facetAddress;
            require(oldFacetAddress == address(0), "LibDiamond: Can't add function that already exists");

            ds.facetFunctionSelectors[_facetAddress].functionSelectors.push(selector);
            ds.selectorToFacetAndPosition[selector] = FacetAddressAndPosition({
                facetAddress: _facetAddress,
                functionSelectorPosition: uint96(ds.facetFunctionSelectors[_facetAddress].functionSelectors.length - 1)
            });
        }
    }

    function replaceFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        require(_facetAddress != address(0), "LibDiamond: Replace facet can't be address(0)");
        enforceHasContractCode(_facetAddress, "LibDiamond: Replace facet has no code");

        DiamondStorage storage ds = diamondStorage();
        uint256 selectorCount = _functionSelectors.length;
        require(selectorCount > 0, "LibDiamond: No selectors in facet to cut");

        if (ds.facetFunctionSelectors[_facetAddress].functionSelectors.length == 0) {
            ds.facetFunctionSelectors[_facetAddress].facetAddressPosition = ds.facetAddresses.length;
            ds.facetAddresses.push(_facetAddress);
        }

        for (uint256 selectorIndex; selectorIndex < selectorCount; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds.selectorToFacetAndPosition[selector].facetAddress;
            require(oldFacetAddress != _facetAddress, "LibDiamond: Can't replace function with same facet");
            require(oldFacetAddress != address(0), "LibDiamond: Can't replace function that doesn't exist");

            removeFunction(oldFacetAddress, selector);
            ds.facetFunctionSelectors[_facetAddress].functionSelectors.push(selector);
            ds.selectorToFacetAndPosition[selector] = FacetAddressAndPosition({
                facetAddress: _facetAddress,
                functionSelectorPosition: uint96(ds.facetFunctionSelectors[_facetAddress].functionSelectors.length - 1)
            });
        }
    }

    function removeFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        require(_facetAddress == address(0), "LibDiamond: Remove facet address must be address(0)");

        uint256 selectorCount = _functionSelectors.length;
        require(selectorCount > 0, "LibDiamond: No selectors in facet to cut");

        for (uint256 selectorIndex; selectorIndex < selectorCount; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = diamondStorage().selectorToFacetAndPosition[selector].facetAddress;
            require(oldFacetAddress != address(0), "LibDiamond: Can't remove function that doesn't exist");
            removeFunction(oldFacetAddress, selector);
        }
    }

    function removeFunction(address _facetAddress, bytes4 _selector) internal {
        DiamondStorage storage ds = diamondStorage();
        FacetFunctionSelectors storage facetSelectors = ds.facetFunctionSelectors[_facetAddress];
        uint256 selectorPosition = ds.selectorToFacetAndPosition[_selector].functionSelectorPosition;
        uint256 lastSelectorPosition = facetSelectors.functionSelectors.length - 1;

        if (selectorPosition != lastSelectorPosition) {
            bytes4 lastSelector = facetSelectors.functionSelectors[lastSelectorPosition];
            facetSelectors.functionSelectors[selectorPosition] = lastSelector;
            ds.selectorToFacetAndPosition[lastSelector].functionSelectorPosition = uint96(selectorPosition);
        }

        facetSelectors.functionSelectors.pop();
        delete ds.selectorToFacetAndPosition[_selector];

        if (facetSelectors.functionSelectors.length == 0) {
            uint256 facetAddressPosition = facetSelectors.facetAddressPosition;
            uint256 lastFacetAddressPosition = ds.facetAddresses.length - 1;

            if (facetAddressPosition != lastFacetAddressPosition) {
                address lastFacetAddress = ds.facetAddresses[lastFacetAddressPosition];
                ds.facetAddresses[facetAddressPosition] = lastFacetAddress;
                ds.facetFunctionSelectors[lastFacetAddress].facetAddressPosition = facetAddressPosition;
            }

            ds.facetAddresses.pop();
            delete ds.facetFunctionSelectors[_facetAddress].facetAddressPosition;
        }
    }

    function initializeDiamondCut(address _init, bytes memory _calldata) internal {
        if (_init == address(0)) {
            require(_calldata.length == 0, "LibDiamond: _init is address(0) but _calldata is not empty");
            return;
        }

        require(_calldata.length > 0, "LibDiamond: _calldata is empty but _init is not address(0)");
        enforceHasContractCode(_init, "LibDiamond: _init address has no code");

        (bool success, bytes memory error) = _init.delegatecall(_calldata);
        if (!success) {
            if (error.length > 0) {
                revert(string(error));
            }
            revert("LibDiamond: _init function reverted");
        }
    }

    function enforceHasContractCode(address _contract, string memory _errorMessage) internal view {
        uint256 contractSize;
        assembly {
            contractSize := extcodesize(_contract)
        }
        require(contractSize > 0, _errorMessage);
    }
}

contracts/facets/ApsdexFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { LibDiamond } from "../DiamondLibrary/LibDiamond.sol";

contract ApsdexFacet {
    event LiquidityInitialized(address indexed provider, uint256 ETH_amount, uint256 APS_amount);
    event LiquidityProvided(address indexed provider, uint256 liquidityMinted, uint256 ethAmount, uint256 tokenAmount);
    event LiquidityRemoved(address indexed provider, uint256 liquidityBurned, uint256 ethAmount, uint256 tokenAmount);

    function token() external view returns (IERC20) {
        return LibDiamond.apsdexStorage().token;
    }

    function ethReserve() external view returns (uint256) {
        return LibDiamond.apsdexStorage().ethReserve;
    }

    function apsReserve() external view returns (uint256) {
        return LibDiamond.apsdexStorage().apsReserve;
    }

    function totalLiquidity() external view returns (uint256) {
        return LibDiamond.apsdexStorage().totalLiquidity;
    }

    function liquidity(address account) external view returns (uint256) {
        return LibDiamond.apsdexStorage().liquidity[account];
    }

    function initialized() external view returns (bool) {
        return LibDiamond.apsdexStorage().initialized;
    }

    function initializePool(uint256 apsAmount) external payable returns (bool) {
        LibDiamond.APSDEXStorage storage s = LibDiamond.apsdexStorage();
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        require(msg.sender == ds.contractOwner, "Only owner can initialize the pool");
        require(!s.initialized, "Already initialized");
        require(msg.value > 0 && apsAmount > 0, "Invalid amounts");
        require(address(s.token) != address(0), "Token not set");

        require(s.token.transferFrom(msg.sender, address(this), apsAmount), "Transfer failed");

        s.ethReserve = msg.value;
        s.apsReserve = apsAmount;
        s.totalLiquidity = msg.value;
        s.liquidity[msg.sender] = msg.value;
        s.initialized = true;

        emit LiquidityInitialized(msg.sender, msg.value, apsAmount);
        return true;
    }

    function price(uint256 _xInput, uint256 _xReserves, uint256 _yReserves) public pure returns (uint256 yOutput) {
        require(_xReserves > 0 && _yReserves > 0, "Reserves must be greater than zero");
        uint256 numerator = _xInput * _yReserves;
        uint256 denominator = _xReserves + _xInput;
        return numerator / denominator;
    }

    function currentPrice() public view returns (uint256) {
        LibDiamond.APSDEXStorage storage s = LibDiamond.apsdexStorage();
        require(s.apsReserve > 0, "APS reserve is zero");
        return (s.ethReserve * 1e18) / s.apsReserve;
    }

    function calculateXInput(uint256 _yOutput, uint256 _xReserves, uint256 _yReserves) public pure returns (uint256 xInput) {
        require(_xReserves > 0 && _yReserves > 0, "Reserves must be greater than zero");
        require(_yOutput < _yReserves, "yOutput must be less than yReserves");
        uint256 numerator = _yOutput * _xReserves;
        uint256 denominator = _yReserves - _yOutput;
        return (numerator / denominator) + 1;
    }

    function ethToToken() internal returns (uint256 tokenOutput) {
        LibDiamond.APSDEXStorage storage s = LibDiamond.apsdexStorage();
        uint256 ethInput = msg.value;
        require(ethInput > 0, "Must send ETH");
        require(s.initialized, "Pool not initialized");

        tokenOutput = (ethInput * s.apsReserve) / s.ethReserve;
        s.ethReserve += ethInput;
        s.apsReserve -= tokenOutput;

        require(s.token.transfer(msg.sender, tokenOutput), "Token transfer failed");
        return tokenOutput;
    }

    function tokenToEth(uint256 tokenInput) internal returns (uint256 ethOutput) {
        LibDiamond.APSDEXStorage storage s = LibDiamond.apsdexStorage();
        require(tokenInput > 0, "Must send tokens");
        require(s.initialized, "Pool not initialized");

        require(s.token.transferFrom(msg.sender, address(this), tokenInput), "Transfer failed");
        ethOutput = (tokenInput * s.ethReserve) / s.apsReserve;

        s.apsReserve += tokenInput;
        s.ethReserve -= ethOutput;

        (bool sent, ) = payable(msg.sender).call{ value: ethOutput }("");
        require(sent, "ETH transfer failed");

        return ethOutput;
    }

    function swap(uint256 tokenInput) external payable returns (uint256 output) {
        if (msg.value > 0) {
            output = ethToToken();
        } else {
            output = tokenToEth(tokenInput);
        }
    }

    function deposit() public payable returns (uint256 tokensDeposited) {
        LibDiamond.APSDEXStorage storage s = LibDiamond.apsdexStorage();
        require(msg.value > 0, "Must send value when depositing");
        require(s.initialized, "Pool not initialized");

        uint256 ethReserveLocal = address(this).balance - msg.value;
        uint256 tokenReserveLocal = s.token.balanceOf(address(this));
        uint256 tokenDeposit = ((msg.value * tokenReserveLocal) / ethReserveLocal) + 1;

        require(s.token.balanceOf(msg.sender) >= tokenDeposit, "insufficient token balance");
        require(s.token.allowance(msg.sender, address(this)) >= tokenDeposit, "insufficient allowance");

        uint256 liquidityMinted = (msg.value * s.totalLiquidity) / ethReserveLocal;
        s.liquidity[msg.sender] += liquidityMinted;
        s.totalLiquidity += liquidityMinted;

        require(s.token.transferFrom(msg.sender, address(this), tokenDeposit));
        emit LiquidityProvided(msg.sender, liquidityMinted, msg.value, tokenDeposit);
        return tokenDeposit;
    }

    function withdraw(uint256 amount) public returns (uint256 ethAmount, uint256 tokenAmount) {
        LibDiamond.APSDEXStorage storage s = LibDiamond.apsdexStorage();
        require(s.liquidity[msg.sender] >= amount, "withdraw: sender does not have enough liquidity to withdraw.");

        uint256 ethReserveLocal = address(this).balance;
        uint256 tokenReserveLocal = s.token.balanceOf(address(this));
        uint256 ethWithdrawn = (amount * ethReserveLocal) / s.totalLiquidity;

        tokenAmount = (amount * tokenReserveLocal) / s.totalLiquidity;
        s.liquidity[msg.sender] -= amount;
        s.totalLiquidity -= amount;

        (bool sent, ) = payable(msg.sender).call{ value: ethWithdrawn }("");
        require(sent, "withdraw(): revert in transferring eth to you!");
        require(s.token.transfer(msg.sender, tokenAmount));

        emit LiquidityRemoved(msg.sender, amount, ethWithdrawn, tokenAmount);
        return (ethWithdrawn, tokenAmount);
    }
}

